use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let input: Vec<Vec<i64>> = input.as_array().unwrap();
    let mut total = 0;
    for item in input {
        let unit_price_cents = item[0];
        let quantity = item[1];
        total += unit_price_cents * quantity;
    }
    serde_json::Value::from(total)
}

fn main() {
    let input = serde_json::Value::from("{\"input\":[[120,2],[99,3]],\"expected\":537}");
    let result = solve(input);
    println!("{:?}", result);
}
